package com.collectiq.web;
import org.springframework.web.bind.annotation.*;import com.collectiq.security.TenantContext;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;
@RestController @RequestMapping("/api/approvals") public class ApprovalController{
 private final JdbcTemplate db;public ApprovalController(JdbcTemplate d){db=d;}
 @GetMapping public List<Map<String,Object>> pending(){return db.queryForList("select id,invoice_id,recipient,message,status,created_at from reminder_approvals where tenant_id=? and status='PENDING' order by created_at",TenantContext.get());}
 @PostMapping public Map<String,Object> create(@RequestBody Map<String,Object>b){Long invoice=Long.valueOf(b.get("invoiceId").toString());String recipient=Objects.toString(b.get("recipient"),"");String message=Objects.toString(b.get("message"),"");if(message.isBlank()||message.length()>4000||recipient.isBlank())throw new IllegalArgumentException("Recipient and message (max 4000 chars) required");String phone=db.queryForObject("select c.phone from invoices i join customers c on c.id=i.customer_id where i.id=? and i.tenant_id=?",String.class,invoice,TenantContext.get());if(phone==null||!phone.equals(recipient))throw new IllegalArgumentException("Recipient must match this tenant invoice customer's phone");db.update("insert into reminder_approvals(tenant_id,invoice_id,recipient,message) values(?,?,?,?)",TenantContext.get(),invoice,recipient,message);return Map.of("queuedForReview",true);}
 @PostMapping("/{id}/approve")public Map<String,Object> approve(@PathVariable long id,@RequestBody Map<String,String>b){int n=db.update("update reminder_approvals set status='APPROVED',approved_by=?,approved_at=now() where id=? and tenant_id=? and status='PENDING'",b.getOrDefault("approvedBy","workspace-admin"),id,TenantContext.get());return Map.of("approved",n==1);}
 @PostMapping("/{id}/reject")public Map<String,Object> reject(@PathVariable long id){int n=db.update("update reminder_approvals set status='REJECTED' where id=? and tenant_id=? and status='PENDING'",id,TenantContext.get());return Map.of("rejected",n==1);}
}